solution:
#include <stdio.h>
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    int tong = 0;
    for (int i = 1; i <= n; i++) tong += i;
    printf("%d\n", tong);
    return 0;
}
